-- Owner-provided content: brand story (About) and AED 17 delivery charge (Shipping); removes filled-in placeholders.
-- Only exact original text is replaced, so anything already edited in Admin → Pages stays as it is.
UPDATE `Page` SET `content` = REPLACE(`content`, 'elegant women''s dresses, soft premium shawls and everyday-to-evening fashion bags in one considered collection.', 'elegant women''s dresses, soft premium shawls and everyday-to-evening fashion bags in one considered collection.\n\n## Our story\n\nFounded in the UAE in 2025, MALAKAND THREADS is a solely women-owned brand for women customers — created to fulfil their daily clothing needs according to their own fashion and style.') WHERE `slug` = 'about' AND `content` NOT LIKE '%## Our story%';
UPDATE `Page` SET `content` = REPLACE(`content`, '\n\n[Business owner: add your story, founding year and any verified trade licence details here before launch.]', '') WHERE `slug` = 'about';
UPDATE `Page` SET `seoDescription` = 'MALAKAND THREADS is a women-owned UAE fashion brand, founded in 2025, offering curated women''s dresses, shawls and fashion bags with Cash on Delivery across all seven emirates.' WHERE `slug` = 'about' AND `seoDescription` = 'MALAKAND THREADS is a UAE online fashion store offering curated women''s dresses, shawls and fashion bags with Cash on Delivery across all seven emirates.';
UPDATE `Page` SET `content` = REPLACE(`content`, 'The delivery fee for your emirate is shown at checkout before you place your order. Orders above the free-delivery threshold shown on the website qualify for free delivery.', 'Delivery charges are **AED 17** across the UAE (charges may vary according to your location). The exact delivery fee is always shown at checkout before you place your order. Orders above the free-delivery threshold shown on the website qualify for free delivery.') WHERE `slug` = 'shipping-policy';
UPDATE `Page` SET `content` = REPLACE(`content`, ' [Business owner: confirm typical dispatch and delivery times before publishing specific timeframes.]', '') WHERE `slug` = 'shipping-policy';
UPDATE `Page` SET `content` = REPLACE(`content`, 'You may request a return within **[7] days** of delivery. [Business owner: confirm the return window — this number must match the "Returns window" setting in the admin panel.]', 'You may request a return within **7 days** of delivery.') WHERE `slug` = 'returns-policy';
-- Remove the remaining owner placeholders from Privacy and Terms (legal details can be added later in Admin → Pages).
UPDATE `Page` SET `content` = REPLACE(`content`, '
[Business owner: add your registered business name and address once confirmed.]', '') WHERE `slug` = 'privacy-policy';
UPDATE `Page` SET `content` = REPLACE(`content`, 'This website is operated by MALAKAND THREADS. [Business owner: insert legal entity name, trade licence number and issuing authority once confirmed.]', 'This website is operated by MALAKAND THREADS, a women-owned business founded in the UAE in 2025.') WHERE `slug` = 'terms-and-conditions';
UPDATE `Page` SET `content` = REPLACE(`content`, ' [Business owner: confirm the emirate whose courts have jurisdiction.]', '') WHERE `slug` = 'terms-and-conditions';
